const response = $json;
const lead = response.items?.[0] ?? response;
const originalOutput = $('AI Agent1').item.json.output ?? '';
const claimsFinal = /credencial\s+(foi\s+)?confirmad|qr\s*code|parab[eé]ns pela sua decis[aã]o/i.test(originalOutput);
const missing = [];
if (!lead.first_name?.trim() || !lead.last_name?.trim()) missing.push('nome completo');
if (!lead.companions?.trim()) missing.push('acompanhantes');
if (!lead.store_visit_datetime) missing.push('data da visita');
const description = (lead.description ?? '').trim().toLowerCase();
if (!description.startsWith('carro na troca:')) missing.push('resposta sobre carro na troca');
if (description.includes('carro na troca: sim')) {
  if (!lead.vehicle_plate?.trim()) missing.push('placa do veículo');
}
const questions = {
  'nome completo': 'Antes de concluir, me confirma seu nome completo?',
  'acompanhantes': 'Antes de concluir, vc vai levar algum acompanhante? Se sim, quantos?',
  'data da visita': 'Antes de concluir, qual dia do evento vc prefere?',
  'resposta sobre carro na troca': 'Antes de concluir, vc pretende dar algum carro na troca?',
  'placa do veículo': 'Antes de concluir, me passa a placa do veículo, por gentileza?',
  'modelo do veículo': 'Antes de concluir, qual é o modelo do veículo?',
  'ano do veículo': 'Antes de concluir, qual é o ano do veículo?'
};
let output = originalOutput;
let needsStatus = false;
let needsMove = false;
let blocked = false;
if (claimsFinal) {
  if (missing.length) {
    blocked = true;
    output = questions[missing[0]];
  } else {
    const finalized = ['scheduled','confirmed'].includes(lead.confirmation_status) && String(lead.crm_stage_code ?? '').endsWith('_PRESENCA_AGENDADA') && Boolean(lead.active_appointment?.id);
    if (!finalized) {
      blocked = true;
      output = 'Não consegui concluir seu credenciamento agora. Seus dados continuam salvos e vou tentar novamente com segurança.';
    }
    needsStatus = false;
    needsMove = false;
  }
}
return { json: { ...lead, output, validator_claims_final: claimsFinal, validator_missing: missing, validator_blocked: blocked, validator_needs_status: needsStatus, validator_needs_move: needsMove } };

const metadata = $json.metadata ?? {};
const message = Array.isArray($json.messages) ? $json.messages[0] : null;
const contact = Array.isArray($json.contacts) ? $json.contacts[0] : null;
if (!message?.id || !message?.from || !metadata.phone_number_id) return [];
const text = message.text?.body ?? message.button?.text ?? message.interactive?.button_reply?.title ?? message.interactive?.list_reply?.title ?? null;
return [{ json: {
  ...$json,
  v2_context: {
    message_id: String(message.id),
    phone_number_id: String(metadata.phone_number_id),
    display_phone_number: metadata.display_phone_number ?? null,
    lead_phone: String(message.from),
    lead_profile_name: contact?.profile?.name ?? null,
    message_type: message.type ?? null,
    message_text: text,
    received_at: message.timestamp ? new Date(Number(message.timestamp) * 1000).toISOString() : new Date().toISOString()
  }
} }];

const response = $('CONSULTAR ETAPA').item.json;
const lead = response.items?.[0] ?? null;
const expectedClient = String($('EverSync').item.json.id_cliente ?? '');
let error = null;
if (!lead?.id) error = 'lead_not_found_after_refresh';
else if (String(lead.client_id ?? '') !== expectedClient) error = 'client_scope_mismatch';
else if (!lead.event_id && !lead.event_interest_id) error = 'event_not_linked';
return [{ json: { ...response, v2_resolution_valid: !error, v2_resolution_error: error, v2_event_id: lead?.event_id ?? lead?.event_interest_id ?? null } }];

const context = $json;
const lead = $('V2 - VALIDAR ESCOPO LEAD EVENTO').item.json.items?.[0] ?? {};
const conversation = context.conversation;
const previous = context.conversation_state?.state_payload ?? {};
const validSteps = new Set(['WAITING_FULL_NAME','WAITING_COMPANIONS','WAITING_COMPANION_NAMES','WAITING_EVENT_DATE','WAITING_TRADE_IN','WAITING_VEHICLE_PLATE','WAITING_VEHICLE_DETAILS','WAITING_FINAL_CONFIRMATION','COMPLETED','CANCELLED','HUMAN_HANDOFF']);
const trade = String(lead.description ?? '').trim().toLowerCase();
const hasFullName = Boolean(lead.first_name?.trim() && lead.last_name?.trim());
const companionsText = String(lead.companions ?? '').trim();
const hasCompanions = Boolean(companionsText);
const companionCount = Number(companionsText.match(/^(\d+)/)?.[1] ?? 0);
const noCompanions = /sem acompanhantes?/i.test(companionsText);
const companionNamesPending = companionCount > 0 && (!companionsText.includes(':') || /nomes? (ainda )?n[aã]o informado/i.test(companionsText));
const hasDate = Boolean(lead.store_visit_datetime);
const hasTradeAnswer = trade.startsWith('carro na troca:');
const tradeYes = trade.includes('carro na troca: sim');
const hasPlate = Boolean(lead.vehicle_plate?.trim());
