let derivedStep;
if (context.flags?.handoff_required) derivedStep = 'HUMAN_HANDOFF';
else if (lead.confirmation_status === 'cancelled') derivedStep = 'CANCELLED';
else if (previous.current_step === 'COMPLETED' || ['confirmed','checked_in','closed'].includes(lead.confirmation_status)) derivedStep = 'COMPLETED';
else if (!hasFullName) derivedStep = 'WAITING_FULL_NAME';
else if (!hasDate) derivedStep = 'WAITING_EVENT_DATE';
else if (!hasCompanions) derivedStep = 'WAITING_COMPANIONS';
else if (!noCompanions && companionNamesPending) derivedStep = 'WAITING_COMPANION_NAMES';
else if (!hasTradeAnswer) derivedStep = 'WAITING_TRADE_IN';
else if (tradeYes && !hasPlate) derivedStep = 'WAITING_VEHICLE_PLATE';
else derivedStep = 'WAITING_FINAL_CONFIRMATION';
const previousStep = validSteps.has(previous.current_step) ? previous.current_step : null;
const terminal = new Set(['COMPLETED','CANCELLED','HUMAN_HANDOFF']);
const currentStep = terminal.has(derivedStep) ? derivedStep : (previousStep && !terminal.has(previousStep) ? derivedStep : derivedStep);
const pendingQuestions = {
 WAITING_FULL_NAME:'Qual é o seu nome completo?', WAITING_COMPANIONS:'Você vai levar algum acompanhante? Se sim, quantos?', WAITING_COMPANION_NAMES:'Qual é o nome completo de cada acompanhante?', WAITING_EVENT_DATE:'Qual dia do evento você prefere?', WAITING_TRADE_IN:'Você pretende dar algum carro na troca?', WAITING_VEHICLE_PLATE:'Qual é a placa do veículo?', WAITING_VEHICLE_DETAILS:'Qual é o modelo e o ano do veículo?', WAITING_FINAL_CONFIRMATION:'Está tudo correto?', COMPLETED:null, CANCELLED:null, HUMAN_HANDOFF:null
};
const collected = { full_name:hasFullName, companions:hasCompanions, companion_names:hasCompanions&&!companionNamesPending, event_date:hasDate, trade_in_answer:hasTradeAnswer, vehicle_plate:hasPlate, vehicle_details:(!tradeYes || hasPlate) };
const missing = [];
if (!hasFullName) missing.push('full_name');
if (!hasDate) missing.push('event_date');
if (!hasCompanions) missing.push('companions');
if (hasCompanions && companionNamesPending) missing.push('companion_names');
if (!hasTradeAnswer) missing.push('trade_in_answer');
if (tradeYes && !hasPlate) missing.push('vehicle_plate');
return [{json:{...context,v2_conversation_id:conversation?.id??null,v2_state_update:{current_intent:'credentialing',awaiting_confirmation:currentStep==='WAITING_FINAL_CONFIRMATION',last_offered_event_id:lead.event_id??lead.event_interest_id??null,last_offered_slot:lead.store_visit_datetime??null,last_agent_action:previous.last_agent_action??null,handoff_required:context.flags?.handoff_required??false,handoff_reason:context.conversation_state?.handoff_reason??null,state_payload:{version:2,current_step:currentStep,pending_question:pendingQuestions[currentStep],collected_fields:collected,missing_fields:missing,last_customer_intent:previous.last_customer_intent??null,last_agent_action:previous.last_agent_action??null,last_tool_result:previous.last_tool_result??null,conversation_status:currentStep,retry_count:Number(previous.retry_count??0),last_message_id:$('V2 - NORMALIZAR ENTRADA').item.json.v2_context.message_id,updated_by:'rubinho_v2_pre_turn'}}}}];

const validated = $json;
const lead = $('VALIDADOR - ANALISAR').item.json;
const trade = String(lead.description ?? '').trim().toLowerCase();
const companionsText=String(lead.companions??'').trim(), companionCount=Number(companionsText.match(/^(\d+)/)?.[1]??0), noCompanions=/sem acompanhantes?/i.test(companionsText), companionNamesPending=companionCount>0&&(!companionsText.includes(':')||/nomes? (ainda )?n[aã]o informado/i.test(companionsText));
const hasFullName=Boolean(lead.first_name?.trim()&&lead.last_name?.trim()), hasCompanions=Boolean(companionsText), hasDate=Boolean(lead.store_visit_datetime), hasTrade=trade.startsWith('carro na troca:'), tradeYes=trade.includes('carro na troca: sim'), hasPlate=Boolean(lead.vehicle_plate?.trim());
const completeData=hasFullName&&hasCompanions&&!companionNamesPending&&hasDate&&hasTrade&&(!tradeYes||hasPlate);
const pre=$('V2 - ESTADO PRONTO').item.json.v2_state??{};
const wasCompleted=pre.current_step==='COMPLETED'||['confirmed','checked_in','closed'].includes(String(lead.confirmation_status??''));
const finalized=wasCompleted||(lead.validator_claims_final===true&&!lead.validator_blocked&&completeData&&Boolean(lead.active_appointment?.id)&&['scheduled','confirmed'].includes(lead.confirmation_status));
let step;
if (lead.confirmation_status==='cancelled') step='CANCELLED';
else if (finalized) step='COMPLETED';
else if(!hasFullName) step='WAITING_FULL_NAME'; else if(!hasDate) step='WAITING_EVENT_DATE'; else if(!hasCompanions) step='WAITING_COMPANIONS'; else if(!noCompanions&&companionNamesPending) step='WAITING_COMPANION_NAMES'; else if(!hasTrade) step='WAITING_TRADE_IN'; else if(tradeYes&&!hasPlate) step='WAITING_VEHICLE_PLATE'; else step='WAITING_FINAL_CONFIRMATION';
const q={WAITING_FULL_NAME:'Qual é o seu nome completo?',WAITING_COMPANIONS:'Você vai levar algum acompanhante? Se sim, quantos?',WAITING_COMPANION_NAMES:'Qual é o nome completo de cada acompanhante?',WAITING_EVENT_DATE:'Qual dia do evento você prefere?',WAITING_TRADE_IN:'Você pretende dar algum carro na troca?',WAITING_VEHICLE_PLATE:'Qual é a placa do veículo?',WAITING_VEHICLE_DETAILS:'Qual é o modelo e o ano do veículo?',WAITING_FINAL_CONFIRMATION:'Está tudo correto?',COMPLETED:null,CANCELLED:null};
const payload={version:2,current_step:step,pending_question:q[step],collected_fields:{full_name:hasFullName,companions:hasCompanions,companion_names:hasCompanions&&!companionNamesPending,event_date:hasDate,trade_in_answer:hasTrade,vehicle_plate:hasPlate,vehicle_details:!tradeYes||hasPlate},missing_fields:[...(lead.validator_missing??[]),...(companionNamesPending?['companion_names']:[])],last_customer_intent:pre.last_customer_intent??null,last_agent_action:validated.v2_qr_delivery?.status==='sent'?'checkin_notification_sent':validated.v2_qr_delivery?.status==='failed'?'checkin_notification_failed':lead.validator_claims_final?'final_confirmation':step,last_tool_result:validated.v2_qr_delivery?.status??(lead.validator_blocked?'blocked':'success'),conversation_status:step,retry_count:(lead.validator_blocked||validated.v2_qr_delivery?.status==='failed')?Number(pre.retry_count??0)+1:0,last_message_id:$('V2 - NORMALIZAR ENTRADA').item.json.v2_context.message_id,updated_by:'rubinho_v2_post_turn'};
return [{json:{...validated,v2_post_state_update:{current_intent:'credentialing',awaiting_confirmation:step==='WAITING_FINAL_CONFIRMATION',last_offered_event_id:lead.event_id??lead.event_interest_id??null,last_offered_slot:lead.store_visit_datetime??null,last_agent_action:payload.last_agent_action,handoff_required:false,state_payload:payload}}}];

const result = { ...$('V2 - CALCULAR ESTADO POS TURNO').item.json };
const normalized = $('V2 - NORMALIZAR ENTRADA').item.json.v2_context ?? {};
const lead = $('VALIDADOR - ANALISAR').item.json ?? {};
const incoming = String(normalized.message_text ?? '').trim();
const isOpeningTrigger = /^(garantir minha vaga|finalizar credenciamento|finalizar credencial|oi|olá|ola|bom dia|boa tarde|boa noite)[!. ]*$/i.test(incoming);
const isWaitingForFullName = !String(lead.first_name ?? '').trim() || !String(lead.last_name ?? '').trim();

if (isOpeningTrigger && isWaitingForFullName) {
  const profileFirstName = String(normalized.lead_profile_name ?? '').trim().split(/\s+/)[0];
  const eventName = String($('RESUMO DO LEAD/EVENTO/RUBINHO').item.json.name ?? 'evento').trim();
  const greetingName = profileFirstName ? ", ${profileFirstName}" : '';
  result.output = `Falaa${greetingName}! Tudo certo? Meu nome é Rubinho, sou assistente virtual do ${eventName} e vou dar continuidade ao seu atendimento. Me informa seu nome completo?`;
}

return [{ json: result }];

const lead=$('VALIDADOR - ANALISAR').item.json;
const response=$json;
const sent=response.sent===true && Boolean(response.appointment_id) && Boolean(response.media_id);
const error=response.error?.message??response.message??response.errorDescription??null;
const output=sent
  ? 'Parabéns! Sua credencial foi confirmada e o QR Code foi enviado por aqui. Te esperamos no evento!'
  : 'Sua credencial foi confirmada, mas não consegui enviar o QR Code agora. Seus dados e seu agendamento estão salvos com segurança.';
return [{json:{...lead,output,v2_qr_delivery:{status:sent?'sent':'failed',appointment_id:lead.active_appointment?.id??null,message_id:response.message_id??null,wamid:response.wamid??null,media_id:response.media_id??null,idempotent_replay:response.idempotent_replay===true,error:sent?null:String(error??'checkin_notification_failed')}}}];

const previous=$('V2 - RESTAURAR APOS AUDITORIA').item.json;
const requested=$json.handoff_required===true;
return [{json:{...previous,output:requested?'Tive uma dificuldade para concluir essa etapa com segurança. Vou encaminhar seu atendimento para nossa equipe continuar com vc.':previous.output,v2_handoff_result:{requested,error:requested?null:($json.error?.message??$json.message??'handoff_request_failed')}}}];

const eventos = $input.all().map(i => i.json).flatMap(j => Array.isArray(j.data) ? j.data : [j]).filter(Boolean);
const ativos = eventos.filter(e => String(e.status || '').toLowerCase() === 'active');
if (!ativos.length) throw new Error('Nenhum evento ativo para criar o lead WhatsApp');
const agora=Date.now();
ativos.sort((a,b)=>{const da=new Date(a.event_end_date||a.event_date||0).getTime();const db=new Date(b.event_end_date||b.event_date||0).getTime();return (da<agora)-(db<agora)||Math.abs(da-agora)-Math.abs(db-agora)});
return [{json:{...ativos[0],selected_event_id:ativos[0].id}}];
